import{_ as r,o as a,c as e,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const q=JSON.parse('{"title":"中美能源（伯克希尔哈撒韦能源）","description":"","frontmatter":{"title":"中美能源（伯克希尔哈撒韦能源）"},"headers":[],"relativePath":"03_companies/中美能源.md","filePath":"03_companies/中美能源.md"}'),i={name:"03_companies/中美能源.md"};function d(o,t,h,s,n,u){return a(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="中美能源-berkshire-hathaway-energy" tabindex="-1">中美能源（Berkshire Hathaway Energy） <a class="header-anchor" href="#中美能源-berkshire-hathaway-energy" aria-label="Permalink to &quot;中美能源（Berkshire Hathaway Energy）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>首次提及</strong>: 1999年</li><li><strong>成立时间</strong>: 1999年（被收购前）</li><li><strong>总部</strong>: 爱荷华州得梅因</li><li><strong>行业</strong>: 能源公用事业</li><li><strong>英文名</strong>: MidAmerican Energy Holdings → Berkshire Hathaway Energy (BHE)</li><li><strong>网站</strong>: berkshirehathawayenergy.com</li></ul><h2 id="收购时间线" tabindex="-1">收购时间线 <a class="header-anchor" href="#收购时间线" aria-label="Permalink to &quot;收购时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>事件</th><th>投资/成本</th></tr></thead><tbody><tr><td>1999年</td><td>伯克希尔首次投资约20亿美元，获得76%权益</td><td>约20亿美元</td></tr><tr><td>2000年</td><td>完成收购，持股76%（监管限制投票权仅9.9%）</td><td>-</td></tr><tr><td>2002年</td><td>收购Kern River和Northern Natural Gas管道</td><td>-</td></tr><tr><td>2003年</td><td>持股增至80.2%</td><td>-</td></tr><tr><td>2005年</td><td>收购PacifiCorp</td><td>34亿美元（伯克希尔出资）+ 17亿美元（债务）</td></tr><tr><td>2006年</td><td>PUHCA废除后，投票权增至83.4%</td><td>-</td></tr><tr><td>2009年</td><td>持股增至89.5%</td><td>-</td></tr><tr><td>2013年</td><td>收购NV Energy</td><td>56亿美元</td></tr><tr><td>2020年</td><td>持股约91%</td><td>-</td></tr><tr><td>2024年</td><td>从约92%提高到100%</td><td>39亿美元（29亿现金+伯克希尔B股）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><h3 id="公用事业运营" tabindex="-1">公用事业运营 <a class="header-anchor" href="#公用事业运营" aria-label="Permalink to &quot;公用事业运营&quot;">​</a></h3><ul><li><strong>英国业务</strong>: 约克郡电力和北方电力，服务360万客户，英国第三大电力分销商</li><li><strong>爱荷华州</strong>: MidAmerican Energy，服务约72万电力客户</li><li><strong>西部六州</strong>: PacifiCorp（太平洋电力和落基山电力），服务约170万客户</li><li><strong>内华达州</strong>: NV Energy，服务约88%人口</li><li><strong>天然气管道</strong>: Kern River和Northern Natural Gas，输送美国约8-9%天然气消耗</li></ul><h3 id="可再生能源领导地位" tabindex="-1">可再生能源领导地位 <a class="header-anchor" href="#可再生能源领导地位" aria-label="Permalink to &quot;可再生能源领导地位&quot;">​</a></h3><ul><li>全美受监管公用事业中风能发电能力第一</li><li>爱荷华州风电装机占总发电容量约20%（收购后从零增长）</li><li>太阳能发电能力全国领先</li><li>已投资超150亿美元于可再生能源项目</li></ul><h3 id="其他业务" tabindex="-1">其他业务 <a class="header-anchor" href="#其他业务" aria-label="Permalink to &quot;其他业务&quot;">​</a></h3><ul><li><strong>HomeServices of America</strong>: 美国第二大房地产经纪公司</li><li><strong>输电业务</strong>: 加拿大AltaLink（服务阿尔伯塔省85%人口）、英国和菲律宾电力业务</li></ul><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h3><p><strong>沃尔特·斯科特（Walter Scott, Jr.）</strong></p><ul><li>小沃尔特·斯科特是巴菲特的长期朋友和邻居</li><li>1999年将中美能源介绍给巴菲特</li><li>交易时用现金购买更多股票使总投资达到约2.8亿美元</li><li>长期担任公司控股股东和董事</li><li>2025年去世，享年87岁</li><li>内布拉斯加州慈善领袖，奥马哈和整个州都留下了他的印记</li></ul><p><strong>戴夫·索科尔（Dave Sokol）</strong></p><ul><li>中美能源杰出管理者，2000年收购时任CEO</li><li>2009年出任NetJets（奈特捷）CEO</li><li>领导中美能源期间实现从零到行业领先的可再生能源布局</li></ul><p><strong>格雷格·阿贝尔（Greg Abel）</strong></p><ul><li>继索科尔之后担任中美能源CEO</li><li>现任伯克希尔哈撒韦能源CEO</li><li>巴菲特指定为伯克希尔下一任CEO候选人之一</li></ul><h3 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h3><blockquote><p>&quot;我们四方所有权的动态完全没有改变。我们将中美能源视为伯克希尔哈撒韦、沃尔特·斯科特和两位出色管理者戴夫·索科尔和格雷格·阿贝尔之间的合作伙伴。各方拥有多少表决权并不重要；只有当我们一致认为某项重大举措是明智的，我们才会采取。戴夫、格雷格和沃尔特合作五年来，我最初的信念得到了加强：伯克希尔哈撒韦找不到更好的合作伙伴了。&quot; — 2005年股东信</p></blockquote><blockquote><p>&quot;与戴夫、格雷格和沃尔特共事六年强化了我最初的信念：伯克希尔哈撒韦不可能有更好的合作伙伴。&quot; — 2006年股东信</p></blockquote><blockquote><p>&quot;戴夫、格雷格和沃尔特合作九年，强化了我最初信念：伯克希尔哈撒韦不可能找到更好的合作伙伴。&quot; — 2008年股东信</p></blockquote><blockquote><p>&quot;与沃尔特·斯科特及其家族合作，自我们购买以来，BHE从未向伯克希尔哈撒韦支付过股息，而且随着时间的推移，保留了280亿美元的收益。这种模式在公用事业领域是一个 outlier，该领域的公司通常支付大额股息——有时达到甚至超过收益的80%。我们的观点：我们能投资的越多，我们越喜欢。&quot; — 2019年股东信</p></blockquote><blockquote><p>&quot;BHE的社会成就记录与其财务表现一样令人瞩目。该公司在2000年没有风能或太阳能发电。当时，它仅被视为庞大电力行业中一个相对较新且较小的参与者。随后，在大卫·索科尔和格雷格·阿贝尔的领导下，BHE已成为一家公用事业巨头以及美国大部分地区风能、太阳能和输电领域的领导力量。&quot; — 2021年股东信</p></blockquote><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><ol><li><strong>多元化收益来源</strong>: 业务覆盖11个州及英国、加拿大、菲律宾等多个国家，免受单一监管机构影响</li><li><strong>可再生能源领导地位</strong>: 全美受监管公用事业风能发电能力第一，太阳能领先</li><li><strong>低成本运营效率</strong>: 爱荷华州电价仅6.8美分/千瓦时，远低于相邻州的9-10美分</li><li><strong>客户满意度</strong>: 2013年客户满意度调查95.3%非常满意，零&quot;不满意&quot;</li><li><strong>资本再投资</strong>: 100%利润留存再投资，持续扩大可再生能源和基础设施</li><li><strong>安全记录行业领先</strong>: BHE安全记录排名行业前10%</li></ol><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>税前利润（百万美元）</th><th>备注</th></tr></thead><tbody><tr><td>2000年</td><td>122</td><td>伯克希尔收购首年</td></tr><tr><td>2002年</td><td>613</td><td>收购Kern River和Northern Natural后</td></tr><tr><td>2003年</td><td>565</td><td>持股80.2%</td></tr><tr><td>2004年</td><td>622</td><td>-</td></tr><tr><td>2005年</td><td>-</td><td>收购PacifiCorp后收入增33亿美元</td></tr><tr><td>2008年</td><td>719</td><td>-</td></tr><tr><td>2009年</td><td>728</td><td>-</td></tr><tr><td>2010年</td><td>1,100+</td><td>业绩持续增长</td></tr><tr><td>2011年</td><td>1,250+</td><td>进入&quot;五大支柱&quot;</td></tr><tr><td>2012年</td><td>1,380</td><td>-</td></tr><tr><td>2013年</td><td>1,430</td><td>&quot;五大支柱&quot;之一，税前利润3.93亿（仅BHE部分）</td></tr><tr><td>2014年</td><td>1,620+</td><td>-</td></tr><tr><td>2019年</td><td>2,000+</td><td>盈利83亿美元（含BNSF铁路）</td></tr><tr><td>2020年</td><td>3,400</td><td>21年间从1.22亿增长到34亿</td></tr><tr><td>2021年</td><td>4,000</td><td>创纪录</td></tr><tr><td>2022年</td><td>4,300</td><td>创纪录</td></tr><tr><td>2023年</td><td>2,331</td><td>下降</td></tr><tr><td>2024年</td><td>3,730</td><td>恢复增长</td></tr></tbody></table><h2 id="关键投资与资本配置" tabindex="-1">关键投资与资本配置 <a class="header-anchor" href="#关键投资与资本配置" aria-label="Permalink to &quot;关键投资与资本配置&quot;">​</a></h2><ul><li><strong>2000年收购</strong>: 约20亿美元获得76%股权</li><li><strong>2002年管道收购</strong>: Kern River和Northern Natural Gas</li><li><strong>2005年PacifiCorp</strong>: 34亿美元股权 + 17亿美元债务</li><li><strong>2013年NV Energy</strong>: 56亿美元</li><li><strong>2014年AltaLink</strong>: 30亿加元</li><li><strong>2024年完全收购</strong>: 39亿美元（29亿现金 + B股）将持股从92%增至100%</li><li><strong>可再生能源投资</strong>: 超150亿美元</li><li><strong>留存收益再投资</strong>: 自收购以来保留约280亿美元利润从未分红</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025</p><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><a href="/04_people/沃尔特·斯科特">沃尔特·斯科特</a> - 介绍人、控股股东、董事（2025年去世）</li><li><a href="/search?q=戴夫·索科尔">戴夫·索科尔</a> - 前CEO（2000-2009），后任NetJets CEO</li><li><a href="/04_people/格雷格·阿贝尔">格雷格·阿贝尔</a> - 现任CEO，伯克希尔CEO候选人</li><li>罗恩·佩尔蒂埃（Ron Peltier）- HomeServices of America CEO</li><li>马特·罗斯（Matt Rose）- BNSF铁路CEO（与中美能源并列比较）</li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> - 母公司，&quot;四大珍宝&quot;之一</li><li><a href="/03_companies/BNSF铁路">BNSF铁路</a> - 另一个&quot;四大珍宝&quot;，常与中美能源一起被提及</li><li><a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a> - 投资者</li></ul><h3 id="历年股东信相关章节" tabindex="-1">历年股东信相关章节 <a class="header-anchor" href="#历年股东信相关章节" aria-label="Permalink to &quot;历年股东信相关章节&quot;">​</a></h3><ul><li><a href="/search?q=1999年股东信">1999年股东信</a> - 首次投资约20亿美元获得76%权益</li><li><a href="/search?q=2000年股东信">2000年股东信</a> - 完成收购，持股76%，收益1.22亿美元</li><li><a href="/search?q=2002年股东信">2002年股东信</a> - 收购Kern River和Northern Natural管道</li><li><a href="/search?q=2003年股东信">2003年股东信</a> - 持股80.2%，沃尔特·斯科特介绍</li><li><a href="/search?q=2004年股东信">2004年股东信</a> - 80.5%持股，HomeServices业务</li><li><a href="/search?q=2005年股东信">2005年股东信</a> - 收购PacifiCorp，PUHCA废除，83.4%投票权</li><li><a href="/search?q=2006年股东信">2006年股东信</a> - 86.6%权益，可再生能源发展</li><li><a href="/search?q=2007年股东信">2007年股东信</a> - 与沃尔特·斯科特合作评价</li><li><a href="/search?q=2008年股东信">2008年股东信</a> - 87.4%权益，风电投资18亿美元，爱荷华州风电第一</li><li><a href="/search?q=2009年股东信">2009年股东信</a> - 89.5%权益，爱荷华风电投资30亿美元</li><li><a href="/search?q=2011年股东信">2011年股东信</a> - &quot;五大支柱&quot;之一</li><li><a href="/search?q=2012年股东信">2012年股东信</a> - 89.8%权益，可再生能源领导者</li><li><a href="/search?q=2013年股东信">2013年股东信</a> - 收购NV Energy，89.8%权益，五大支柱之一</li><li><a href="/search?q=2014年股东信">2014年股东信</a> - BHE数据，11个州业务，可再生能源6%风电7%太阳能</li><li><a href="/search?q=2015年股东信">2015年股东信</a> - 爱荷华风电47%覆盖，PacifiCorp安全改善</li><li><a href="/search?q=2016年股东信">2016年股东信</a> - 回顾收购决策</li><li><a href="/search?q=2017年股东信">2017年股东信</a> - HomeServices增长，收购</li><li><a href="/search?q=2019年股东信">2019年股东信</a> - 91%权益，280亿美元留存收益，风电自给自足</li><li><a href="/search?q=2020年股东信">2020年股东信</a> - 91%权益，34亿美元收益，&quot;四大珍宝&quot;之一</li><li><a href="/search?q=2021年股东信">2021年股东信</a> - 91.1%权益，40亿美元收益，增长30多倍</li><li><a href="/search?q=2022年股东信">2022年股东信</a> - 92%权益，43亿美元收益</li><li><a href="/search?q=2023年股东信">2023年股东信</a> - 92%权益，23.31亿美元收益</li><li><a href="/search?q=2024年股东信">2024年股东信</a> - 从约92%提高到100%，39亿美元代价</li></ul><hr><p><em>本档案基于巴菲特1999-2025年致股东信原文编写</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/2000年/翻译">/01_letters/2000年/翻译</a></li><li><a href="/01_letters/2002年/翻译">/01_letters/2002年/翻译</a></li><li><a href="/01_letters/翻译">/01_letters//翻译</a></li><li><a href="/01_letters/翻译">/01_letters//翻译</a></li></ul>',45)])])}const g=r(i,[["render",d]]);export{q as __pageData,g as default};
